// Primary SLO thresholds (from perf-config.json slo.*)
export const P95_THRESHOLD_MS = { p95_threshold_ms }; // slo.p95_threshold_ms
export const ERROR_RATE_THRESHOLD = { error_rate_threshold }; // slo.error_rate_threshold (e.g. 0.01 = 1%)

// Abort thresholds — stress and spike tests only.
// Set to null for load and soak tests.
export const ABORT_P95_MS = { abort_p95_ms }; // null if not applicable
export const ABORT_ERROR_RATE = { abort_error_rate }; // null if not applicable

/**
 * k6 thresholds object — import this in your test script options.
 *
 * Usage:
 *   import { thresholds } from '../../tests/config/thresholds.js';
 *   export const options = { stages, thresholds };
 */
export const thresholds = (() => {
  const t = {
    http_req_duration: [`p(95)<${P95_THRESHOLD_MS}`],
    http_req_failed: [`rate<${ERROR_RATE_THRESHOLD}`],
  };

  // Add abortOnFail for stress and spike tests
  if (ABORT_P95_MS !== null) {
    t.http_req_duration = [
      {
        threshold: `p(95)<${ABORT_P95_MS}`,
        abortOnFail: true,
        delayAbortEval: "30s",
      },
    ];
  }

  if (ABORT_ERROR_RATE !== null) {
    t.http_req_failed = [
      {
        threshold: `rate<${ABORT_ERROR_RATE}`,
        abortOnFail: true,
        delayAbortEval: "30s",
      },
    ];
  }

  return t;
})();
